final class NativeRampPartDataChecks {
 private static int cases,checks,compactMaximum,expandedMaximum;private static final int[] NONE={-1,-1,-1,-1,-1,-1};
 static void run(ServerLevel level)throws Exception{
  round(level,Blocks.STONE.defaultBlockState(),8,false);for(var half:SlabType.values())round(level,Blocks.STONE_SLAB.defaultBlockState().setValue(SlabBlock.TYPE,half),8,false);
  for(var face:Direction.values()){round(level,VandorLabsBootstrap.PROGRAMMABLE_BLOCK.get().defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING,face),8,true);for(var half:Half.values())round(level,VandorLabsBootstrap.PROGRAMMABLE_SLAB.get().defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING,face).setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.HALF,half),8,true);if(face.getAxis().isVertical())continue;for(var half:Half.values())for(var shape:StairsShape.values()){var vanilla=Blocks.COBBLESTONE_STAIRS.defaultBlockState().setValue(StairBlock.FACING,face).setValue(StairBlock.HALF,half).setValue(StairBlock.SHAPE,shape);round(level,vanilla,8,false);var nativeState=VandorLabsBootstrap.PROGRAMMABLE_STAIRS.get().defaultBlockState().setValue(StairBlock.FACING,face).setValue(StairBlock.HALF,half).setValue(StairBlock.SHAPE,shape);for(int tread:new int[]{1,2,4,8,16})for(int roll=0;roll<3;roll++)round(level,nativeState,StairState.packed(tread,roll),true);}}
  var data=example(Blocks.STONE.defaultBlockState(),8,false);var encoded=data.write();need(data.observed(108).motion().observed()==.25&&data.observed(108).materials()==data.materials(),"observed motion reuses static materials without geometry recreation");var belt=data.withBelt(new NativeRampPartData.Belt(1,2,.5,100,true,.5));need(NativeRampPartData.read(belt.write(),data.spec().cell(),level.registryAccess()).belt().equals(belt.belt()),"belt phase/speed separate from ordinary motion");
  var s=data.spec();var shifted=new NativeRampPartData.Origin(s.cell().relative(s.facing().getOpposite()),8,data.origins().get(0).material());var overhangSpec=new NativeRampGeometry.Spec(s.cell(),s.facing(),s.sourceY(),3,s.length(),s.treadPixels(),s.low(),s.high(),s.start(),s.end(),s.elevator(),s.travel(),s.extend(),s.fast(),s.interpolation(),s.verticalLayout(),s.moat(),s.shaped(),List.of(shifted.geometry()));var overhang=new NativeRampPartData(overhangSpec,data.original(),List.of(shifted),data.motion(),belt.belt());need(NativeRampPartData.read(overhang.write(),s.cell(),level.registryAccess()).spec().row()==3,"actual belt overhang row is never normalized by the legacy cell writer");
  var mutable=encoded.copy();var decoded=NativeRampPartData.read(mutable,s.cell(),level.registryAccess());mutable.getList("Origins",Tag.TAG_COMPOUND).getCompound(0).getIntArray("Faces")[0]=0;need(decoded.write().equals(encoded),"decoded descriptor does not retain caller tag arrays");var faces=decoded.origins().get(0).material().faces();faces[0]=0;need(decoded.write().equals(encoded),"material face accessor is defensive");boolean immutable=false;try{decoded.materials().clear();}catch(UnsupportedOperationException expected){immutable=true;}need(immutable,"material map immutable");
  for(int malformed=0;malformed<9;malformed++){var bad=encoded.copy();switch(malformed){case 0->bad.putInt("Schema",99);case 1->bad.putString("Low","future");case 2->bad.putDouble("End",Double.NaN);case 3->bad.putByte("Facing",(byte)1);case 4->bad.put("Items",new ListTag());case 5->{var list=new ListTag();for(int i=0;i<129;i++)list.add(encoded.getList("Origins",Tag.TAG_COMPOUND).getCompound(0).copy());bad.put("Origins",list);}case 6->bad.getList("Origins",Tag.TAG_COMPOUND).getCompound(0).putIntArray("Offset",new int[]{65,0,0});case 7->bad.getCompound("Motion").putInt("Duration",0);default->bad.getList("Origins",Tag.TAG_COMPOUND).getCompound(0).putIntArray("Faces",new int[]{1,2});}boolean refused=false;try{NativeRampPartData.read(bad,data.spec().cell(),level.registryAccess());}catch(IllegalArgumentException expected){refused=true;}need(refused,"malformed/ownership-like compact payload refused case="+malformed);}
  need(cases==662,"all source recipe variants");System.out.println("[vandorlabs][ramp-part-data] PASS variants="+cases+" checks="+checks+" compactMaxBytes="+compactMaximum+" expandedBoxMaxBytes="+expandedMaximum+" native recipe codec only");
 }
 private static NativeRampPartData example(BlockState state,int packed,boolean housing){var pos=new BlockPos(22880,100,22880);boolean stairs=state.getBlock() instanceof com.vandorlabs.neoforge.shape.NativeProgrammableStairs;var material=new NativeRampPartMaterial(state,housing?0:-1,housing&&stairs?1:-1,housing?1:-1,0,housing&&stairs,housing,housing?new int[]{0,-1,0,-1,0,-1}:NONE);var origin=new NativeRampPartData.Origin(pos,packed,material);var shape=origin.geometry();double low=shape.shapes().stream().mapToDouble(b->b.minY).min().orElseThrow(),high=shape.shapes().stream().mapToDouble(b->b.maxY).max().orElseThrow();var spec=new NativeRampGeometry.Spec(pos,Direction.NORTH,pos.getY(),2,3,8,low,high,0,-2,false,0,false,false,0,false,false,state.getBlock() instanceof StairBlock,List.of(shape));return new NativeRampPartData(spec,state,List.of(origin),new NativeRampPartData.Motion(7,100,0,1,32,true,0));}
 private static void round(ServerLevel level,BlockState state,int packed,boolean housing)throws Exception{var original=example(state,packed,housing);var encoded=original.write();var decoded=NativeRampPartData.read(encoded,original.spec().cell(),level.registryAccess());need(decoded.write().equals(encoded)&&decoded.spec().equals(original.spec())&&decoded.original()==original.original()&&decoded.materials().equals(original.materials()),"complete recipe round trip case="+cases);need(NativeRampGeometry.snapshot(decoded.spec(),.375).pieces().equals(NativeRampGeometry.snapshot(original.spec(),.375).pieces()),"collision geometry round trip case="+cases);String text=encoded.toString();need(!text.contains("ForgeCaps")&&!text.contains("SourceTiles")&&!text.contains("Items")&&!text.contains("Operation"),"projection excludes physical ownership case="+cases);int compact=bytes(encoded);var expanded=encoded.copy();var entries=expanded.getList("Origins",Tag.TAG_COMPOUND);for(int i=0;i<entries.size();i++){var entry=entries.getCompound(i);entry.remove("Shape");entry.remove("Stair");var boxes=new ListTag();for(var box:original.spec().origins().get(i).shapes()){var words=new ListTag();for(double n:new double[]{box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ})words.add(DoubleTag.valueOf(n));boxes.add(words);}entry.put("Boxes",boxes);}compactMaximum=Math.max(compactMaximum,compact);expandedMaximum=Math.max(expandedMaximum,bytes(expanded));cases++;}
 private static int bytes(CompoundTag tag)throws Exception{var output=new java.io.ByteArrayOutputStream();NbtIo.write(tag,new java.io.DataOutputStream(output));return output.size();}
 private static void need(boolean ok,String text){checks++;if(!ok)throw new AssertionError("Ramp compact projection: "+text);}
}
